// Allocate temporary buffer for read operation
std::unique_ptr<std::uint8_t[]> read_buffer(new std::uint8_t[hint]);

// Read from block device using cache-aware read
lfs_ssize_t read_size = lfs_bd_read(lfs, block, off, read_buffer.get(), size);
if (read_size < 0) {
    return static_cast<int>(read_size);
}

// Compare with provided buffer
int cmp_result = std::memcmp(read_buffer.get(), buffer, static_cast<std::size_t>(read_size));

// Handle cache hints if provided
if (pcache != nullptr) {
    lfs_cache_hint(pcache, block, off, read_size);
}
if (rcache != nullptr) {
    lfs_cache_hint(rcache, block, off, read_size);
}

// Return comparison result
if (cmp_result == 0) {
    return LFS_CMP_EQ;
} else if (cmp_result < 0) {
    return LFS_CMP_LT;
} else {
    return LFS_CMP_GT;
}

